# shellcheck shell=bash
# box distdeb: how far this host is from a fresh Debian install plus what
# box installs. Sourced by box (uses say, ok, warn, need_root, PKG_BASE,
# PKG_DOCKER). Reports only; it removes nothing. Review each list, and move
# files you do not want into /root/cruft/ for a while instead of deleting.

# Files that are normal on any Debian host without belonging to a package:
# generated by maintainer scripts, caches, host identity, enabled-unit links.
DISTDEB_NOISE=(
	'^/etc/(machine-id|hostname|hosts|fstab|mtab|resolv\.conf|adjtime|timezone|localtime|mailname|motd|issue(\.net)?|papersize)$'
	'^/etc/(passwd|group|shadow|gshadow|subuid|subgid)-?$'
	'^/etc/(ld\.so\.cache|\.pwd\.lock|ca-certificates\.conf|locale\.gen|environment|shells)$'
	# Written by maintainer scripts or the installer, on every Debian.
	'^/etc/(nsswitch\.conf|networks|inputrc|modules|kernel-img\.conf|locale\.conf|hosts\.(allow|deny)|\.updated|\.resolv\.conf\.[a-z-]+\.bak)$'
	'^/etc/pam\.d/common-'
	'^/etc/initramfs-tools/modules$'
	'^/etc/dpkg/origins/default$'
	'^/etc/apparmor\.d/(local|disable|force-complain|cache)/'
	'^/etc/apparmor\.d/tunables/[^/]+\.d/'
	'^/etc/apt/(apt\.conf\.d/(20auto-upgrades|50unattended-upgrades)|listchanges\.conf|sources\.list\.d/debian\.sources)$'
	# The cloud image's own setup (orion, lyra): how the provider boots it.
	'^/etc/(cloud/|netplan/|default/grub\.d/|grub\.d/enable_cloud$|cloud-release$|apt/mirrors/)'
	'^/etc/modprobe\.d/blacklist\.conf$'
	'^/etc/default/(grub|keyboard|locale|console-setup|useradd)$'
	'^/etc/(ssl/certs|alternatives|rc[0-6S]\.d)/'
	'^/etc/ssh/ssh_host_(rsa|ecdsa|ed25519)_key(\.pub)?$'
	'^/etc/network/interfaces$'
	'^/etc/ssh/sshd_config$'   # written by openssh-server's postinst (ucf); checked against /usr/share/openssh/sshd_config
	'^/etc/udev/(rules\.d/70-persistent-|hwdb\.bin$)'
	'^/etc/initramfs-tools/conf\.d/resume$'
	'^/etc/systemd/(system|user)/.*\.(wants|requires)/'
	'^/etc/apt/apt\.conf\.d/01autoremove-kernels$'
	'^/etc/apt/sources\.list$'   # reported in its own section
	'^/etc/mdadm/mdadm\.conf$'
	'^/etc/lvm/(archive|backup)/'
	'^/etc/console-setup/cached'
	'^/etc/X11/xkb/'
	'^/etc/(sgml|xml)/(catalog|.*\.cat)'
	'(^|/)__pycache__/|\.pyc$'
	'^/usr/lib/locale/locale-archive$'
	'^/usr/share/info/dir(\.old)?$'
	'^/usr/share/mime/'
	'^/usr/share/icons/[^/]+/icon-theme\.cache$'
	'^/usr/share/glib-2\.0/schemas/gschemas\.compiled$'
	'^/usr/share/applications/mimeinfo\.cache$'
	'^/usr/share/fonts/.*fonts\.(dir|scale)$'
	'^/usr/lib/[^/]*-linux-gnu/(gdk-pixbuf-2\.0/.*/loaders\.cache|gio/modules/giomodule\.cache|gconv/gconv-modules\.cache)$'
	'^/usr/lib/udev/hwdb\.bin$'
	'^/usr/lib/modules/'
	'^/usr/lib/python3/dist-packages/.*\.(dist|egg)-info/'
)

# Names of backup and upgrade leftovers (their own section).
DISTDEB_LEFTOVER='\.(dpkg-(old|dist|new|bak)|ucf-[a-z]+|bak|old|orig|stretch|buster|bullseye|bookworm)$|~$'

# What box itself installs (box audit checks those against the repository).
DISTDEB_BOX=(
	'^/etc/(srv|docker|containers)/'
	'^/etc/(cron\.d/srv|msmtprc|aliases\.msmtp|tmux\.conf|gitconfig|vim/vimrc\.local|containerd/config\.toml)$'
	'^/etc/ssh/sshd?_config\.d/srv\.conf$'
	'^/etc/systemd/(journald|resolved)\.conf\.d/srv\.conf$'
	'^/etc/sysctl\.d/99-srv-podman\.conf$'
	'^/etc/modules-load\.d/srv-podman\.conf$'
	'^/etc/fail2ban/(jail\.local|(jail|filter|action)\.d/srv-)'
	'^/etc/apt/(apt\.conf\.d/99srv-minimal|sources\.list\.d/docker\.sources|keyrings/docker\.asc)$'
	'^/etc/cloud/cloud\.cfg\.d/99-srv\.cfg$'
	'^/etc/ssh/srv-port-confirmed$'
	'^/etc/systemd/resolved\.conf\.d/srv\.conf$'
	'^/usr/local/bin/(srv|box|remote)$'
)

# distdeb_owned: every path dpkg knows, with the merged /usr layout applied
# (packages list /bin/x, the file is /usr/bin/x), sorted.
distdeb_owned() {
	{
		cat /var/lib/dpkg/info/*.list
		dpkg-divert --list 2>/dev/null | sed -n 's/.* to \(.*\) by .*/\1/p'
	} | sed -E 's#^/(bin|sbin|lib|lib32|lib64|libx32)/#/usr/\1/#' | LC_ALL=C sort -u
}

# distdeb_filter: drop the noise (and what box installs) from a path list.
# Unit links in /etc/systemd/system (systemctl enable, mask) are left out
# by the find itself. /home is never scanned: it is yours.
distdeb_filter() {
	local managed=()
	# What box recorded installing (install_file), on top of the list above.
	[[ -s ${MANAGED_LIST:-} ]] && mapfile -t managed < <(sed 's/[][\.*^$+?(){}|]/\\&/g; s/.*/^&$/' "$MANAGED_LIST")
	grep -Ev -f <(printf '%s\n' "${DISTDEB_NOISE[@]}" "${DISTDEB_BOX[@]}" "${managed[@]}") || true
}

# not_box_backup: drop the .bak copies box keeps when it replaces a file it
# manages (install_file), /etc/hosts included.
not_box_backup() {
	local f
	while IFS= read -r f; do
		if [[ $f == *.bak ]] && { [[ ${f%.bak} == /etc/hosts ]] || [[ -z $(distdeb_filter <<<"${f%.bak}") ]]; }; then
			continue
		fi
		printf '%s\n' "$f"
	done
}

distdeb_list() { # distdeb_list TITLE < lines: a section, or ok when empty
	local title=$1 lines n
	lines=$(cat)
	n=$(grep -c . <<<"$lines" || true)
	if [[ $n -eq 0 ]]; then
		ok "$title: none"
	else
		warn "$title: $n"
		head -n "${DISTDEB_MAX:-40}" <<<"$lines" | sed 's/^/         /'
		((n <= ${DISTDEB_MAX:-40})) || echo "         ... $((n - ${DISTDEB_MAX:-40})) more (box distdeb --all)"
	fi
}

cmd_distdeb() {
	need_root
	# A report: a missing folder or an empty list must not stop it.
	local -
	set +e +o pipefail
	[[ ${1:-} == --all ]] && DISTDEB_MAX=100000
	local owned
	owned=$(mktemp)
	distdeb_owned >"$owned"

	say "files no package owns (in /etc, /usr, /opt; known noise and box's files left out)"
	find /etc /usr /opt -xdev \( -type f -o \( -type l ! -path '/etc/systemd/system/*' \) \) 2>/dev/null | LC_ALL=C sort |
		LC_ALL=C comm -23 - "$owned" | distdeb_filter | not_box_backup | { grep -vE "$DISTDEB_LEFTOVER" || true; } |
		distdeb_list "unowned files"

	say "configuration files changed from the package's version"
	{
		{ dpkg --verify 2>/dev/null || true; } | awk '$2 == "c" {print $3}' | distdeb_filter
		if [[ -f /etc/ssh/sshd_config && -f /usr/share/openssh/sshd_config ]] &&
			! cmp -s /etc/ssh/sshd_config /usr/share/openssh/sshd_config; then
			echo "/etc/ssh/sshd_config (differs from /usr/share/openssh/sshd_config)"
		fi
	} | distdeb_list "changed config files"

	say "upgrade leftovers"
	find /etc -type f 2>/dev/null | { grep -E "$DISTDEB_LEFTOVER" || true; } | grep -v '^/etc/\.resolv\.conf\.' |
		sort | not_box_backup | distdeb_list "backup and upgrade files in /etc"
	dpkg -l | awk '/^rc/ {print $2}' | distdeb_list "removed packages with config left (dpkg --purge)"
	{
		if command -v sshd >/dev/null && [[ -d /run/sshd ]]; then
			sshd -t 2>&1 || true
		fi
	} | distdeb_list "deprecated or invalid sshd settings (sshd -t)"

	say "packages"
	apt list '?obsolete' 2>/dev/null | sed -n 's#/.*##p' | distdeb_list "obsolete (in no repository)"
	apt list '?narrow(?installed, ?not(?origin(Debian)))' 2>/dev/null | sed -n 's#/.*##p' |
		distdeb_list "installed from outside Debian"
	local manual libs
	local -a keep=()
	mapfile -t keep < <(
		{
			printf '%s\n' "${PKG_BASE[@]}" "${PKG_PODMAN[@]}"
			# What a minimal install marks manual: required and important priority.
			dpkg-query -W -f='${Package} ${Priority}\n' | awk '$2 == "required" || $2 == "important" {print $1}'
			# Boot, kernels, initramfs, disks, and man-db (installed by box man).
			printf '%s\n' initramfs-tools linux-image-amd64 linux-image-cloud-amd64 \
				grub-pc grub-efi-amd64 ifupdown mdadm lvm2 firmware-linux-free \
				openssh-client sudo locales man-db
			{ dpkg-query -W -f='${Package} ${db:Status-Abbrev}\n' 'linux-image-*' 2>/dev/null || true; } |
				awk '$2 ~ /^ii/ {print $1}'
			# What a cloud image needs to boot and resize itself (orion/lyra).
			printf '%s\n' cloud-init cloud-guest-utils cloud-initramfs-growroot grub-cloud-amd64
		} | sort -u
	)
	manual=$(apt-mark showmanual | { grep -vxF -f <(
		printf '%s\n' "${keep[@]}"
		if ((${#keep[@]} > 0)); then
			apt-cache depends --installed --recurse \
				--no-recommends --no-suggests --no-conflicts --no-breaks --no-replaces --no-enhances \
				"${keep[@]}" 2>/dev/null | awk '/^[a-z0-9]/ {sub(/:.*/, "", $1); print $1}'
		fi
	) || true; })
	# Libraries marked manual (image builders do that) are harmless: apt keeps
	# the ones something needs. One line for all of them, not one each.
	libs=$(grep -E '^lib|-base$' <<<"$manual" || true)
	grep -vE '^lib|-base$' <<<"$manual" | distdeb_list "marked manual beyond a minimal install and box's set (apt-mark auto, then apt autoremove)"
	if [[ -n $libs ]]; then
		echo "  also $(grep -c . <<<"$libs") libraries marked manual: apt-mark auto \$(apt-mark showmanual | grep -E '^lib|-base\$') && apt autoremove --purge"
	fi

	say "kernels and modules"
	local k installed
	installed=$({ dpkg -l 'linux-image-[0-9]*' 2>/dev/null || true; } | awk '/^ii/ {sub("linux-image-", "", $2); print $2}')
	for k in /lib/modules/*/; do
		[[ -d $k ]] || continue
		k=$(basename "$k")
		grep -qxF "$k" <<<"$installed" || echo "/lib/modules/$k"
	done | distdeb_list "module folders of kernels no longer installed"
	find /var/lib/dkms -mindepth 1 -maxdepth 1 2>/dev/null | { grep -vE '/(mok\.(key|pub)|dkms_dbversion)$' || true; } |
		distdeb_list "dkms modules"

	say "apt sources and keys"
	# A fresh trixie has its sources in sources.list.d/debian.sources (deb822).
	{ [[ -s /etc/apt/sources.list ]] && grep -qv '^\s*\(#\|$\)' /etc/apt/sources.list &&
		echo "/etc/apt/sources.list (old one-line format: apt modernize-sources converts it)"; true; } |
		distdeb_list "old-style sources.list"
	find /etc/apt/sources.list.d -type f 2>/dev/null | { grep -vxE '/etc/apt/sources\.list\.d/debian\.sources' || true; } |
		distdeb_list "extra sources"
	{ [[ -e /etc/apt/trusted.gpg ]] && echo /etc/apt/trusted.gpg; true; } | distdeb_list "legacy keyring (apt-key era)"
	find /etc/apt/trusted.gpg.d -type f 2>/dev/null | { grep -v '/debian-archive-' || true; } | distdeb_list "extra keys"

	say "started on their own"
	find /etc/cron.d /etc/cron.hourly /etc/cron.daily /etc/cron.weekly /etc/cron.monthly -type f 2>/dev/null |
		LC_ALL=C sort | LC_ALL=C comm -23 - "$owned" | distdeb_filter | not_box_backup | distdeb_list "cron jobs no package owns"
	{ crontab -l -u root 2>/dev/null | grep -v '^#' | grep . | sed 's/^/root: /'
		awk -F: '$3 >= 1000 && $3 < 60000 {print $1}' /etc/passwd | while read -r u; do
			crontab -l -u "$u" 2>/dev/null | grep -v '^#' | grep . | sed "s/^/$u: /"
		done; true; } | distdeb_list "user crontabs"
	{ [[ -e /etc/rc.local ]] && echo /etc/rc.local; true; } | distdeb_list "rc.local"

	rm -f "$owned"
	echo "  Reported only: nothing was changed. box audit covers listening ports, services and accounts."
}
